func TestIsCveFixed(t *testing.T) {
	type In struct {
		v    models.VulnInfo
		prev models.ScanResult
	}
	var tests = []struct {
		in       In
		expected bool
	}{
		{
			in: In{
				v: models.VulnInfo{
					CveID: "CVE-2016-6662",
					AffectedPackages: models.PackageFixStatuses{
						{
							Name:        "mysql-libs",
							NotFixedYet: false,
						},
					},
					CveContents: models.NewCveContents(
						models.CveContent{
							Type:         models.Nvd,
							CveID:        "CVE-2016-6662",
							LastModified: time.Time{},
						},
					),
				},
				prev: models.ScanResult{
